<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getComboDetail, getComboList, replaceCartComboDish, replaceComboDish } from '../../../api/user/combos'
import { getDishList } from '../../../api/user/dishes'
import { addToCart, getCartList } from '../../../api/user/cart'
import { resolveFileUrl } from '../../../utils/fileUrl'

const loading = ref(false); const combos = ref<any[]>([]); const dishes = ref<any[]>([]); const total = ref(0); const currentPage = ref(1); const pageSize = ref(9); const keyword = ref(''); const comboType = ref<number | undefined>(); const sort = ref('latest'); const detailVisible = ref(false); const detail = ref<any>(null); const rels = ref<any[]>([]); const replacements = ref<Record<string, number | string>>({}); const adding = ref(false)
// 无图套餐用首字徽章占位，不再回退到无关素材图
const comboImageUrl = (combo: any) => resolveFileUrl(combo?.comboImage) || ''
const typeName = (type?: number) => ({ 10: '减脂', 20: '增肌', 30: '控糖', 40: '会员专属' } as Record<number, string>)[type || 0] || '健康方案'
const fetchData = async () => { loading.value = true; try { const [comboRes, dishRes] = await Promise.all([getComboList({ keyword: keyword.value || undefined, comboType: comboType.value, sort: sort.value, page: currentPage.value, size: pageSize.value }), getDishList({ page: 1, size: 100 })]); combos.value = comboRes.data?.data?.list || []; total.value = comboRes.data?.data?.total || 0; dishes.value = dishRes.data?.data?.list || [] } catch { ElMessage.error('加载套餐失败') } finally { loading.value = false } }
const applyFilters = () => { currentPage.value = 1; fetchData() }
// 菜品/套餐 id 是雪花 ID（字符串），一律 String 比较，禁止 Number() 强转
const dishById = (id: number | string) => dishes.value.find(dish => String(dish.id) === String(id))
const fixed = (rel: any) => Number(rel.isFixed) === 1
const selectedId = (rel: any) => replacements.value[rel.dishId] || rel.dishId
const showDetail = async (combo: any) => { try { const response = await getComboDetail(combo.id); detail.value = response.data?.combo || combo; rels.value = response.data?.dishRels || []; replacements.value = {}; detailVisible.value = true } catch { ElMessage.error('获取套餐详情失败') } }
const replaceDish = async (rel: any, newId: number | string) => { if (fixed(rel) || !newId || String(newId) === String(selectedId(rel))) return; if (rels.value.some(item => item !== rel && String(selectedId(item)) === String(newId))) return ElMessage.warning('同一套餐不能重复选择相同菜品'); try { await replaceComboDish(detail.value.id, rel.dishId, newId); replacements.value[rel.dishId] = newId; ElMessage.success('套餐菜品已更新') } catch { ElMessage.error('该菜品暂不可替换') } }
const addCombo = async () => { if (!detail.value || adding.value) return; adding.value = true; try { await addToCart(20, undefined, detail.value.id, 1); const response = await getCartList(); const cart = (response.data || []).find((item: any) => String(item.comboId) === String(detail.value.id)); for (const [oldId, newId] of Object.entries(replacements.value)) if (cart) await replaceCartComboDish(cart.id, oldId, newId); ElMessage.success('套餐已加入购物车'); detailVisible.value = false } catch { ElMessage.error('加入购物车失败') } finally { adding.value = false } }
onMounted(fetchData)
</script>

<template><div class="combo-page"><header class="combo-hero"><div><span>健康套餐</span><h1>把一日营养，安排得恰到好处。</h1><p>按减脂、增肌或控糖目标，找到适合你的组合。</p></div></header><div class="combo-filters"><el-input v-model="keyword" clearable placeholder="搜索套餐" @keyup.enter="applyFilters" @clear="applyFilters" /><el-select v-model="comboType" clearable placeholder="全部目标" @change="applyFilters"><el-option label="减脂" :value="10" /><el-option label="增肌" :value="20" /><el-option label="控糖" :value="30" /><el-option label="会员专属" :value="40" /></el-select><el-select v-model="sort" @change="applyFilters"><el-option label="最新上架" value="latest" /><el-option label="价格从低到高" value="priceAsc" /><el-option label="价格从高到低" value="priceDesc" /><el-option label="热量最低" value="calories" /><el-option label="蛋白质最高" value="protein" /><el-option label="销量优先" value="sales" /></el-select><el-button type="primary" @click="applyFilters">搜索</el-button></div><div v-loading="loading" class="combo-grid"><article v-for="(combo,index) in combos" :key="combo.id" class="combo-card"><button class="combo-image" @click="showDetail(combo)"><img v-if="comboImageUrl(combo)" :src="comboImageUrl(combo)" :alt="combo.comboName" /><span v-else class="img-placeholder">{{ (combo.comboName || '餐')[0] }}</span><span>{{ combo.totalCalories || 0 }} kcal</span></button><div class="combo-body"><div class="combo-title"><div><small>{{ typeName(combo.comboType) }}</small><h2>{{ combo.comboName }}</h2></div><strong>¥{{ combo.price }}</strong></div><p>{{ combo.description || '为日常目标准备的均衡搭配。' }}</p><div class="nutrition"><span>蛋白质 {{ combo.totalProtein || 0 }}g</span><span>碳水 {{ combo.totalCarbs || 0 }}g</span></div><button class="combo-action" @click="showDetail(combo)">查看套餐 <span>→</span></button></div></article><div v-if="!loading && !combos.length" class="empty">暂无符合条件的套餐</div></div><div class="pager"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" :total="total" :page-sizes="[9,18,36]" layout="prev, pager, next" @current-change="fetchData" /></div><el-dialog v-model="detailVisible" title="套餐详情" width="680px"><template v-if="detail"><div class="detail-head"><img v-if="comboImageUrl(detail)" :src="comboImageUrl(detail)" :alt="detail.comboName" /><span v-else class="img-placeholder detail-img-placeholder">{{ (detail.comboName || '餐')[0] }}</span><div><span>{{ typeName(detail.comboType) }}</span><h2>{{ detail.comboName }}</h2><p>{{ detail.description }}</p><strong>¥{{ detail.price }}</strong></div></div><h3>套餐内容</h3><div class="dish-list"><div v-for="rel in rels" :key="rel.id" class="dish-row"><span>{{ dishById(selectedId(rel))?.dishName || `菜品 #${selectedId(rel)}` }}</span><el-tag size="small" :type="fixed(rel) ? 'info' : 'success'">{{ fixed(rel) ? '固定搭配' : '可替换' }}</el-tag><el-select v-if="!fixed(rel)" :model-value="selectedId(rel)" size="small" @change="(id: number) => replaceDish(rel,id)"><el-option v-for="dish in dishes" :key="dish.id" :label="dish.dishName" :value="dish.id" /></el-select></div></div></template><template #footer><el-button @click="detailVisible = false">稍后再看</el-button><el-button type="primary" :loading="adding" @click="addCombo">加入购物车</el-button></template></el-dialog></div></template>

<style scoped>.combo-page{max-width:1192px;margin:0 auto;padding:60px 24px 90px;color:#1f2a24}.combo-hero{padding:8px 0 30px;border-bottom:1px solid #dfe7df}.combo-hero span{color:var(--orange);font-size:12px;font-weight:700;letter-spacing:.14em}.combo-hero h1{margin:12px 0 8px;font-family:"Source Han Serif SC","Songti SC",serif;font-size:38px;font-weight:600}.combo-hero p{margin:0;color:#718078;font-size:14px}.combo-filters{display:flex;gap:10px;margin:24px 0}.combo-filters :deep(.el-input){max-width:330px}.combo-filters :deep(.el-select){width:150px}.combo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px 22px;min-height:280px}.combo-card{display:flex;flex-direction:column;background:#fff;border-bottom:1px solid #dfe7df}.combo-image{position:relative;width:100%;height:230px;padding:0;border:0;overflow:hidden;background:#eef2ed;cursor:pointer}.combo-image img{width:100%;height:100%;object-fit:cover}.combo-image span{position:absolute;right:12px;bottom:12px;padding:5px 8px;background:#fff;color:var(--green);font-size:11px}.combo-body{display:flex;flex:1;flex-direction:column;padding:16px 2px}.combo-title{display:flex;justify-content:space-between;gap:12px}.combo-title small{color:var(--orange);font-size:10px}.combo-title h2{margin:6px 0 0;font-size:18px}.combo-title strong{color:var(--green);font-size:17px}.combo-body p{min-height:38px;margin:9px 0;color:#718078;font-size:12px;line-height:1.6}.nutrition{display:flex;gap:14px;color:#78857d;font-size:11px}.combo-action{align-self:flex-end;margin-top:auto;padding:8px 12px;border:1px solid #c9dbce;background:#f5f8f4;color:var(--green);font-size:12px;cursor:pointer}.combo-action span{color:var(--orange);margin-left:6px}.empty{grid-column:1/-1;padding:80px;text-align:center;color:#9aa69e}.pager{display:flex;justify-content:center;margin-top:38px}.detail-head{display:grid;grid-template-columns:200px 1fr;gap:22px;align-items:center}.detail-head img{width:200px;height:160px;object-fit:cover}.detail-head span{color:var(--orange);font-size:11px}.detail-head h2{margin:9px 0;font-family:"Source Han Serif SC","Songti SC",serif}.detail-head p{color:#718078;font-size:13px;line-height:1.7}.detail-head strong{color:var(--green);font-size:24px}.dish-list{border-top:1px solid #e1e9e2}.dish-row{display:grid;grid-template-columns:minmax(0,1fr) auto 180px;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #edf1ec;font-size:13px}.combo-page :deep(.el-dialog__header){border-bottom:1px solid #edf1ec}.combo-page :deep(.el-dialog__footer){border-top:1px solid #edf1ec}@media(max-width:800px){.combo-grid{grid-template-columns:repeat(2,1fr)}.combo-filters{flex-wrap:wrap}.combo-filters :deep(.el-input){max-width:none;width:100%}}@media(max-width:540px){.combo-page{padding:42px 18px 68px}.combo-hero h1{font-size:31px}.combo-grid{grid-template-columns:1fr}.combo-filters :deep(.el-select){flex:1;width:auto}.combo-filters .el-button{width:80px}.detail-head{grid-template-columns:1fr}.detail-head img{width:100%;height:190px}.dish-row{grid-template-columns:1fr auto}.dish-row :deep(.el-select){grid-column:1/-1;width:100%}}
</style>
<style scoped>
.combo-image .img-placeholder{display:flex;align-items:center;justify-content:center;width:100%;height:100%;position:static;padding:0;background:var(--green-soft);color:var(--green-deep);font-family:"Source Han Serif SC","Songti SC",serif;font-size:44px;font-weight:600;letter-spacing:0}
.detail-head .img-placeholder{display:flex;align-items:center;justify-content:center;width:200px;height:160px;background:var(--green-soft);color:var(--green-deep);font-family:"Source Han Serif SC","Songti SC",serif;font-size:40px;font-weight:600}
